from sys import stdin
input = stdin.readline
inp = lambda : list(map(int, input().split()))

def b_s(take, left, right):
	(l, h) = (0, len(take) - 1)
	while l <= h:
		mid = (l + h) // 2
		if take[mid] < left:
			l = mid + 1
			continue
		if take[mid] > right:
			h = mid - 1
			continue
		return take[mid]

def sparse_query(b, left, right):
	dist = right - left + 1
	if dist == 0:
		return 0
	for i in range(19, -1, -1):
		if dist >> i & 1:
			msb = i
			break
	return max(b[left][msb], b[right - (1 << msb) + 1][msb])

def sparse_table(b):
	for j in range(1, 20):
		for i in range(n - (1 << j - 1)):
			b[i][j] = max(b[i][j - 1], b[i + (1 << j - 1)][j - 1])

def answer():
	best_ans = [[0 for i in range(20)] for j in range(n)]
	best_suf = [[0 for i in range(20)] for j in range(n)]
	best_pref = [[0 for i in range(20)] for j in range(n)]
	takes = dict()
	takep = dict()
	total = [0]
