		best_ans[i][0] = ans
		(ans, sval) = (0, 0)
		for j in s[i]:
			if j == '1':
				sval += 1
			else:
				sval -= 1
			ans = max(ans, sval)
		best_pref[i][0] = ans - max(0, sval)
		total.append(total[-1] + max(0, sval))
		key = ans - max(0, sval)
		if key not in takep:
